PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX v: <https://w3id.org/smtg/vocab/>
SELECT ?variant ?template ?query WHERE {
  ?variant smtg:hasTemplateRequirement/smtg:requiresTemplate ?t . ?t rdfs:label ?template . OPTIONAL { ?t smtg:templateQuery ?query }
}

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX v: <https://w3id.org/smtg/vocab/>
SELECT ?printing ?set ?printedName ?printedText WHERE {
  ?card a smtg:OracleCard ; smtg:name "Lightning Bolt" .
  ?printing smtg:isPrintingOf ?card ; smtg:inLanguage <https://w3id.org/smtg/vocab/language/it> ;
            smtg:inSet/smtg:setCode ?set ; smtg:hasPrintedFace ?pf .
  ?pf smtg:hasPrintedText ?n . ?n a smtg:PrintedName ; smtg:textValue ?printedName .
  OPTIONAL { ?pf smtg:hasPrintedText ?t . ?t a smtg:PrintedRulesText ; smtg:textValue ?printedText . }
}

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT ?card ?token ?mana WHERE {
  GRAPH <https://w3id.org/smtg/graph/inferred/rules> { ?c smtg:producesManaViaToken ?m ; smtg:createsToken ?t . }
  ?c smtg:name ?card . ?t smtg:name ?token . ?t smtg:producesManaSymbol ?m . ?m skos:notation ?mana .
}

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT ?card ?primaryFace ?permanentCard WHERE {
  ?c a smtg:OracleCard ; smtg:name ?card ; smtg:hasFace ?f1 , ?f2 . FILTER(?f1 != ?f2)
  OPTIONAL { ?c smtg:primaryFace/smtg:name ?primaryFace }
  BIND(EXISTS { GRAPH <https://w3id.org/smtg/graph/inferred/rules> { ?c a smtg:PermanentCard } } AS ?permanentCard)
} GROUP BY ?card ?primaryFace ?permanentCard ORDER BY ?card

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT ?c WHERE {
  ?c smtg:name "Agadeem's Awakening // Agadeem, the Undercrypt" .
  GRAPH <https://w3id.org/smtg/graph/inferred/rules> { ?c a smtg:PermanentCard }
}

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX v: <https://w3id.org/smtg/vocab/>
SELECT ?faceName ?kind WHERE {
  { ?f smtg:hasNoManaCost true ; smtg:name ?faceName . BIND("no mana cost" AS ?kind) }
  UNION
  { ?f smtg:hasManaCost/smtg:manaCostNotation "{0}" ; smtg:name ?faceName . BIND("cost {0}" AS ?kind) }
} ORDER BY ?kind ?faceName

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX v: <https://w3id.org/smtg/vocab/>
SELECT ?faceName ?power ?toughness WHERE {
  ?f smtg:name ?faceName ; smtg:powerText ?power ; smtg:toughnessText ?toughness .
  FILTER NOT EXISTS { ?f smtg:powerValue ?pv . ?f smtg:toughnessValue ?tv . }
} ORDER BY ?faceName

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT ?s ?p WHERE {
  { ?s smtg:producesManaViaToken ?o . BIND(smtg:producesManaViaToken AS ?p) }
  UNION { ?s smtg:createsToken ?o . BIND(smtg:createsToken AS ?p) }
  UNION { ?s a smtg:PermanentCard . BIND(smtg:PermanentCard AS ?p) }
}

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT ?date ?by ?status (SUBSTR(?text, 1, 100) AS ?ruling) WHERE {
  ?r a smtg:Ruling ; smtg:rulingFor/smtg:name "Blood Artist" ; smtg:publishedOn ?date ; smtg:rulingText ?text ;
     smtg:claimedBy/rdfs:label ?by ; smtg:hasEpistemicStatus/skos:notation ?status .
} ORDER BY ?date

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT DISTINCT ?set ?code ?printedSize ?cards ?parent WHERE {
  ?p smtg:isPrintingOf/smtg:name "Lightning Bolt" ; smtg:inSet ?s . ?s rdfs:label ?set ; smtg:setCode ?code .
  OPTIONAL { ?s smtg:printedSize ?printedSize } OPTIONAL { ?s smtg:declaredCardCount ?cards } OPTIONAL { ?s smtg:parentSet/smtg:setCode ?parent }
} ORDER BY ?code

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT ?face ?symbol ?kind WHERE {
  ?f smtg:hasManaCost/smtg:hasSymbolOccurrence/smtg:occurrenceOf ?s ; smtg:name ?face . ?s skos:notation ?symbol .
  { ?s smtg:isHybrid true . BIND("hybrid" AS ?kind) } UNION { ?s smtg:isPhyrexian true . BIND("Phyrexian" AS ?kind) }
}

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX v: <https://w3id.org/smtg/vocab/>
SELECT ?tag (COUNT(?parent) AS ?parents) (GROUP_CONCAT(?pl; separator=', ') AS ?parentLabels) WHERE {
  ?t smtg:taggerParent ?parent ; skos:prefLabel ?tag . OPTIONAL { ?parent skos:prefLabel ?pl }
} GROUP BY ?tag HAVING (COUNT(?parent) > 1) ORDER BY DESC(?parents) ?tag

PREFIX smtg: <https://w3id.org/smtg/ontology#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX v: <https://w3id.org/smtg/vocab/>
SELECT ?a ?target WHERE {
  ?a a smtg:ArtTagAssignment ; smtg:assignmentTarget ?target . FILTER NOT EXISTS { ?target a smtg:Illustration }
}
